const byKey = new Map(iconLibrary.map((icon) => [icon.key, icon]));

/** A library icon by key, or null for a key this site doesn't know */
export function libraryIcon(
  key: string | null | undefined,
): LibraryIcon | null {
  return (key && byKey.get(key)) || null;
}
